// Construct a persistent read-only buffer and wrap it with pn_bytes().
// Enforce: if start is non-NULL, it must reference at least `size` readable bytes
// for the lifetime of any consumer. We allocate a heap buffer to satisfy lifetime.

// Choose a size in [0, 1024] to keep allocations small per guidance.
size_t size = (size_t)(*FUZZ_PARAM(unsigned int) % 1025);

// Random content source; will be copied into our persistent buffer if we use one.
std::string src = FUZZ_PARAM_STR();
if (src.empty()) { src = "\x00"; }

// Occasionally exercise the NULL-start case, but only when size == 0 so it is trivially valid.
bool use_null_start = (size == 0) && ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);

char *allocated = nullptr;
if (!use_null_start) {
    // Allocate at least `size` bytes and fill with data to ensure readability.
    size_t cap = size == 0 ? 1 : size; // ensure non-zero allocation when size==0
    allocated = new char[cap];
    for (size_t i = 0; i < cap; ++i) {
        allocated[i] = src[i % src.size()];
    }
}

// Call the target function to package the view.
pn_bytes_t tmp = pn_bytes(size, (const char*)allocated);

// Create an output object for the fuzzer pool and copy the value.
pn_bytes_t *bytes = new pn_bytes_t; // output must never be null
*bytes = tmp;

// We also output a buffer owner pointer so the runtime can retain lifetime.
// If we used a NULL start, still provide a non-null owner pointer by allocating a 1-byte dummy.
void *buf_owner = nullptr;
if (allocated) {
    buf_owner = (void*)allocated;
} else {
    // start==NULL path exercised: allocate a harmless dummy to satisfy non-null output requirement
    char *dummy = new char[1];
    dummy[0] = 0;
    buf_owner = (void*)dummy;
}

// Attach attributes for downstream validation/lifetime tracking.
FUZZ_SET_ATTR_INT(bytes, "size", (int)size);
FUZZ_SET_ATTR_PTR(bytes, "buf", (void*)allocated); // may be NULL if start==NULL
FUZZ_SET_ATTR_STR(bytes, "mut", "const");

// Property checks: the function should faithfully package the inputs.
FUZZ_ASSERT(bytes->size == size, "pn_bytes: size not preserved");
FUZZ_ASSERT(bytes->start == (const char*)allocated, "pn_bytes: pointer not preserved");

// Validation: This stub guarantees readable lifetime by heap-allocating when start!=NULL, and tracks
// ownership via buf_owner. It also exercises the NULL-start case only when size==0.

