import random
import string
from typing import List

# Data type: ASCII identifier string
# Used by stubs for: condition names, symbols, URL scheme, hostnames, descriptors, etc.
# We generate a single bytes buffer that FUZZ_PARAM_STR/FUZZ_PARAM_FILENAME will read from.
# Strategy: produce a compact corpus that concatenates multiple NUL-terminated strings
# covering typical valid cases: AMQP condition names (with colon), symbols, URL schemes,
# hostnames, short/long, mixed chars, edge label lengths, and varying sizes. All 7-bit ASCII.
# The buffer is <= 4096 bytes.

SAFE_ASCII = string.ascii_letters + string.digits + "-_.:/@"
SYMBOL_ASCII = string.ascii_letters + string.digits + "-_./:"
SCHEME_ASCII = string.ascii_lowercase + string.digits + "+-."
HOST_LABEL_CHARS = string.ascii_letters + string.digits + "-"

def _rand_choice(r: random.Random, s: str) -> str:
    return s[r.randrange(len(s))]

def _rand_str(r: random.Random, alphabet: str, min_len: int, max_len: int) -> str:
    n = r.randint(min_len, max_len)
    return "".join(_rand_choice(r, alphabet) for _ in range(n))

def _condition_name(r: random.Random) -> str:
    # Common AMQP condition style: "amqp:category-error" or vendor like "com.example:code"
    # Ensure non-empty and ASCII, with a single ':' separator
    namespaces = [
        "amqp", "amqp", "amqp",  # weight towards standard
        "com.example", "org.apache", "io.qpid", "net.test"
    ]
    ns = r.choice(namespaces)
    # category and token
    cat = _rand_str(r, string.ascii_lowercase + string.digits + "-", 3, 10)
    tok = _rand_str(r, string.ascii_lowercase + string.digits + "-", 3, 12)
    return f"{ns}:{cat}-{tok}"

def _symbol(r: random.Random) -> str:
    # AMQP symbol: 7-bit ASCII, typically printable and short
    # Occasionally produce very short or moderately long (up to 64)
    if r.random() < 0.2:
        n = r.randint(1, 3)
    elif r.random() < 0.8:
        n = r.randint(4, 20)
    else:
        n = r.randint(21, 64)
    s = _rand_str(r, SYMBOL_ASCII, n, n)
    # Avoid leading/trailing spaces or invalids (we don't include spaces anyway)
    return s

def _url_scheme(r: random.Random) -> str:
    # RFC: scheme starts with alpha, then alpha/digit/+/ - / .
    first = _rand_choice(r, string.ascii_lowercase)
    rest_len = r.randint(0, 10)
    rest = _rand_str(r, SCHEME_ASCII, rest_len, rest_len)
    return first + rest

def _hostname(r: random.Random) -> str:
    # Build domain with labels [1..5], each label 1..63, start/end alnum
    num_labels = r.randint(1, 4)
    labels: List[str] = []
    for i in range(num_labels):
        # Occasionally push a 63-length label boundary
        if r.random() < 0.15:
            L = 63
        else:
            L = r.randint(1, 20)
        if L == 1:
            label = _rand_choice(r, string.ascii_letters + string.digits)
        else:
            mid_len = max(0, L - 2)
            start = _rand_choice(r, string.ascii_letters + string.digits)
            mid = _rand_str(r, HOST_LABEL_CHARS, mid_len, mid_len)
            end = _rand_choice(r, string.ascii_letters + string.digits)
            label = start + mid + end
        labels.append(label)
    host = ".".join(labels)
    # Ensure total length <= 255
    if len(host) > 255:
        host = host[:255]
        # trim trailing dot if present
        if host.endswith('.'):
            host = host[:-1]
        # remove trailing '-' if needed
        while host and host[-1] == '-':
            host = host[:-1]
        if not host:
            host = "a"
    return host

def _uuid_like_symbol(r: random.Random) -> str:
    # 32 hex or 36 with dashes
    if r.random() < 0.5:
        parts = [
            _rand_str(r, string.hexdigits.lower(), 8, 8),
            _rand_str(r, string.hexdigits.lower(), 4, 4),
            _rand_str(r, string.hexdigits.lower(), 4, 4),
            _rand_str(r, string.hexdigits.lower(), 4, 4),
            _rand_str(r, string.hexdigits.lower(), 12, 12),
        ]
        return "-".join(parts)
    else:
        return _rand_str(r, string.hexdigits.lower(), 32, 32)

def _numeric_string(r: random.Random) -> str:
    # Useful for %u, %lld conversions in format calls
    if r.random() < 0.5:
        return str(r.randint(0, 2**32 - 1))
    else:
        # 64-bit range
        return str(r.randint(0, 2**63 - 1))

def _small_words(r: random.Random) -> str:
    words = ["ok", "error", "ready", "open", "close", "flow", "credit", "link", "session", "conn"]
    return r.choice(words)

def _assemble_strings(r: random.Random) -> List[bytes]:
    # Create a pool of strings; many consumers will pop sequentially via FUZZ_PARAM_STR.
    items: List[str] = []

    # Ensure at least one strong condition name
    items.append(_condition_name(r))
    # Additional condition-like names
    for _ in range(r.randint(2, 5)):
        items.append(_condition_name(r))

    # Symbols and descriptors
    for _ in range(r.randint(3, 8)):
        items.append(_symbol(r))

    # URL schemes
    for _ in range(r.randint(1, 3)):
        items.append(_url_scheme(r))

    # Hostnames
    for _ in range(r.randint(2, 5)):
        items.append(_hostname(r))

    # UUID-like tokens for use when building 16-byte UUIDs from string bytes
    for _ in range(r.randint(2, 4)):
        items.append(_uuid_like_symbol(r))

    # Some numeric strings
    for _ in range(r.randint(2, 5)):
        items.append(_numeric_string(r))

    # Some very short identifiers
    for _ in range(r.randint(2, 5)):
        items.append(_small_words(r))

    # Add a couple of longer symbols up to 128 to exercise truncation in stubs
    for _ in range(r.randint(1, 2)):
        items.append(_rand_str(r, SYMBOL_ASCII, 80, 128))

    # Guarantee no empty strings (stubs may bail on empty)
    items = [s if s else "x" for s in items]

    # Deduplicate occasionally to reduce size
    if r.random() < 0.3:
        seen = set()
        uniq: List[str] = []
        for s in items:
            if s not in seen:
                seen.add(s)
                uniq.append(s)
        items = uniq

    # Convert to NUL-terminated bytes segments
    out: List[bytes] = []
    for s in items:
        # Ensure 7-bit ASCII by encoding and replacing non-ASCII with '-'
        b = s.encode('ascii', 'ignore')
        if not b:
            b = b"x"
        out.append(b + b"\x00")
    return out

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    segments = _assemble_strings(r)
    blob = b"".join(segments)
    # Ensure buffer size <= 4096; trim at last NUL to avoid partial string
    if len(blob) > 4096:
        blob = blob[:4096]
        # Ensure ends with NUL
        if not blob.endswith(b"\x00"):
            # Backtrack to last NUL
            last = blob.rfind(b"\x00")
            if last != -1:
                blob = blob[:last+1]
            else:
                # fallback: force-terminate
                blob = blob[:-1] + b"\x00"
    return blob

import random
import struct
import time
from typing import List

# This generator produces valid AMQP 1.0 encodings for a single value or a full AMQP message
# as bytes. It aims to cover a wide range of simple and composite types per the encoding specs.
# The buffers are kept <= 4096 bytes.

# AMQP format codes (subset)
NULL = 0x40
BOOL = 0x56           # boolean (one byte: 0x00 or 0x01)
BOOL_TRUE = 0x41      # boolean true (no content)
BOOL_FALSE = 0x42     # boolean false (no content)
UBYTE = 0x50
BYTE = 0x51
USHORT = 0x60
SHORT = 0x61
UINT = 0x70
SMALLUINT = 0x52
UINT0 = 0x43
INT = 0x71
SMALLINT = 0x54
CHAR = 0x73
ULONG = 0x80
SMALLULONG = 0x53
ULONG0 = 0x44
LONG = 0x81
SMALLLONG = 0x55
TIMESTAMP = 0x83
FLOAT = 0x72
DOUBLE = 0x82
DECIMAL32 = 0x74
DECIMAL64 = 0x84
DECIMAL128 = 0x94
UUID = 0x98
BINARY8 = 0xA0
BINARY32 = 0xB0
STRING8 = 0xA1
STRING32 = 0xB1
SYMBOL8 = 0xA3
SYMBOL32 = 0xB3
LIST0 = 0x45
LIST8 = 0xC0
LIST32 = 0xD0
MAP8 = 0xC1
MAP32 = 0xD1
ARRAY8 = 0xE0
ARRAY32 = 0xF0
DESCRIBED_TYPE = 0x00

# Common AMQP descriptors (ulong) for message sections
DESC_HEADER = 0x70
DESC_DELIVERY_ANNOTATIONS = 0x71
DESC_MESSAGE_ANNOTATIONS = 0x72
DESC_PROPERTIES = 0x73
DESC_APPLICATION_PROPERTIES = 0x74
DESC_BODY_DATA = 0x75
DESC_BODY_SEQUENCE = 0x76
DESC_BODY_VALUE = 0x77
DESC_FOOTER = 0x78

MAX_SIZE = 4096


def _rand_bool(r: random.Random) -> bytes:
    if r.choice([True, False]):
        return bytes([BOOL_TRUE])
    v = r.getrandbits(1)
    return bytes([BOOL, v])


def _rand_small_bytes(r: random.Random, max_len: int = 64) -> bytes:
    n = r.randint(0, max_len)
    return bytes(r.getrandbits(8) for _ in range(n))


def _put_uint(n: int) -> bytes:
    return struct.pack('>I', n & 0xFFFFFFFF)


def _put_ulong(n: int) -> bytes:
    # pack as unsigned 64-bit
    return struct.pack('>Q', n & 0xFFFFFFFFFFFFFFFF)


def _put_ushort(n: int) -> bytes:
    return struct.pack('>H', n & 0xFFFF)


def _put_short(n: int) -> bytes:
    # signed 16
    n = max(-2**15, min(2**15 - 1, n))
    return struct.pack('>h', n)


def _put_int(n: int) -> bytes:
    # signed 32
    n = max(-2**31, min(2**31 - 1, n))
    return struct.pack('>i', n)


def _put_long(n: int) -> bytes:
    # signed 64
    n = max(-2**63, min(2**63 - 1, n))
    return struct.pack('>q', n)


def _atom_scalar(r: random.Random) -> bytes:
    # Generate a broad selection of scalar encodings
    choice = r.randrange(0, 20)
    if choice == 0:
        return bytes([NULL])
    if choice == 1:
        return _rand_bool(r)
    if choice == 2:
        return bytes([UBYTE, r.getrandbits(8)])
    if choice == 3:
        return bytes([BYTE, (r.randint(-128, 127) & 0xFF)])
    if choice == 4:
        return bytes([USHORT]) + _put_ushort(r.getrandbits(16))
    if choice == 5:
        return bytes([SHORT]) + _put_short(r.randint(-32768, 32767))
    if choice == 6:
        v = r.getrandbits(32)
        if v == 0:
            return bytes([UINT0])
        if v < 256 and r.random() < 0.5:
            return bytes([SMALLUINT, v & 0xFF])
        return bytes([UINT]) + _put_uint(v)
    if choice == 7:
        v = r.randint(-2**31, 2**31 - 1)
        if -128 <= v <= 127 and r.random() < 0.5:
            return bytes([SMALLINT, v & 0xFF])
        return bytes([INT]) + _put_int(v)
    if choice == 8:
        cp = r.getrandbits(32)
        return bytes([CHAR]) + _put_uint(cp)
    if choice == 9:
        v = r.getrandbits(64)
        if v == 0:
            return bytes([ULONG0])
        if v < 256 and r.random() < 0.5:
            return bytes([SMALLULONG, v & 0xFF])
        return bytes([ULONG]) + _put_ulong(v)
    if choice == 10:
        v = r.randint(-2**63, 2**63 - 1)
        if -128 <= v <= 127 and r.random() < 0.5:
            return bytes([SMALLLONG, v & 0xFF])
        return bytes([LONG]) + _put_long(v)
    if choice == 11:
        # timestamp is ms since epoch as int64
        v = int(time.time() * 1000) + r.randint(-10_000_000, 10_000_000)
        return bytes([TIMESTAMP]) + _put_long(v)
    if choice == 12:
        # float
        return bytes([FLOAT]) + struct.pack('>f', r.uniform(-1e6, 1e6))
    if choice == 13:
        # double
        return bytes([DOUBLE]) + struct.pack('>d', r.uniform(-1e12, 1e12))
    if choice == 14:
        # decimal32 as raw 4 bytes
        return bytes([DECIMAL32]) + _put_uint(r.getrandbits(32))
    if choice == 15:
        return bytes([DECIMAL64]) + _put_ulong(r.getrandbits(64))
    if choice == 16:
        return bytes([DECIMAL128]) + bytes(r.getrandbits(8) for _ in range(16))
    if choice == 17:
        return bytes([UUID]) + bytes(r.getrandbits(8) for _ in range(16))
    if choice == 18:
        # binary
        data = _rand_small_bytes(r, 80)
        if len(data) < 256:
            return bytes([BINARY8, len(data)]) + data
        else:
            return bytes([BINARY32]) + _put_uint(len(data)) + data
    # 19: string or symbol
    if r.random() < 0.5:
        text_bytes = _rand_small_bytes(r, 80)
        if len(text_bytes) < 256:
            return bytes([STRING8, len(text_bytes)]) + text_bytes
        else:
            return bytes([STRING32]) + _put_uint(len(text_bytes)) + text_bytes
    else:
        sym = _rand_small_bytes(r, 80)
        if len(sym) < 256:
            return bytes([SYMBOL8, len(sym)]) + sym
        else:
            return bytes([SYMBOL32]) + _put_uint(len(sym)) + sym


def _encode_list(r: random.Random, max_elems: int = 6) -> bytes:
    elems: List[bytes] = []
    count = r.randint(0, max_elems)
    for _ in range(count):
        elems.append(_encode_any(r, depth=1))
    payload = b''.join(elems)
    if count == 0 and r.random() < 0.5:
        return bytes([LIST0])
    if len(payload) + 1 + 1 < 255 and count < 255:  # size byte and count byte fit in LIST8 total size
        total_size = len(payload) + 1  # count byte included in size field
        return bytes([LIST8, total_size & 0xFF, count & 0xFF]) + payload
    else:
        total_size = len(payload) + 4  # count ui32
        return bytes([LIST32]) + _put_uint(total_size) + _put_uint(count) + payload


def _encode_map(r: random.Random, max_pairs: int = 4) -> bytes:
    pairs = r.randint(0, max_pairs)
    entries: List[bytes] = []
    for _ in range(pairs):
        # keys are symbols or strings usually
        if r.random() < 0.6:
            key = _encode_symbol(r)
        else:
            key = _encode_string(r)
        val = _encode_any(r, depth=1)
        entries.append(key + val)
    payload = b''.join(entries)
    count_entries = pairs * 2
    if len(payload) + 1 + 1 < 255 and count_entries < 255:
        total_size = len(payload) + 1
        return bytes([MAP8, total_size & 0xFF, count_entries & 0xFF]) + payload
    else:
        total_size = len(payload) + 4
        return bytes([MAP32]) + _put_uint(total_size) + _put_uint(count_entries) + payload


def _encode_array(r: random.Random, max_elems: int = 8) -> bytes:
    # Homogeneous array without described type; pick fixed-width or simple base types
    kind = r.choice(['ubyte', 'uint', 'long', 'double', 'boolean'])
    values: List[bytes] = []
    if kind == 'ubyte':
        fmt_code = UBYTE
        for _ in range(r.randint(0, max_elems)):
            values.append(bytes([r.getrandbits(8)]))
    elif kind == 'uint':
        fmt_code = UINT
        for _ in range(r.randint(0, max_elems)):
            values.append(_put_uint(r.getrandbits(32)))
    elif kind == 'long':
        fmt_code = LONG
        for _ in range(r.randint(0, max_elems)):
            values.append(_put_long(r.randint(-2**63, 2**63 - 1)))
    elif kind == 'double':
        fmt_code = DOUBLE
        for _ in range(r.randint(0, max_elems)):
            values.append(struct.pack('>d', r.uniform(-1e6, 1e6)))
    else:  # boolean -> encode as BOOL with single byte content in array
        fmt_code = BOOL
        for _ in range(r.randint(0, max_elems)):
            values.append(bytes([r.choice([0, 1])]))

    elems_payload = b''.join(values)
    # size = element typecode(1) + values
    size = 1 + len(elems_payload)
    count = len(values)
    if size + 2 < 256 and count < 256:
        return bytes([ARRAY8, size & 0xFF, count & 0xFF, fmt_code]) + elems_payload
    else:
        return bytes([ARRAY32]) + _put_uint(size) + _put_uint(count) + bytes([fmt_code]) + elems_payload


def _encode_symbol(r: random.Random) -> bytes:
    data = _rand_small_bytes(r, 40)
    if len(data) < 256:
        return bytes([SYMBOL8, len(data)]) + data
    return bytes([SYMBOL32]) + _put_uint(len(data)) + data


def _encode_string(r: random.Random) -> bytes:
    data = _rand_small_bytes(r, 80)
    if len(data) < 256:
        return bytes([STRING8, len(data)]) + data
    return bytes([STRING32]) + _put_uint(len(data)) + data


def _encode_any(r: random.Random, depth: int = 0) -> bytes:
    # Combine scalars and composites with a bias to keep size small
    if depth > 2:
        return _atom_scalar(r)
    choice = r.randrange(0, 8)
    if choice <= 3:
        return _atom_scalar(r)
    if choice == 4:
        return _encode_list(r)
    if choice == 5:
        return _encode_map(r)
    if choice == 6:
        return _encode_array(r)
    # described value occasionally (e.g., a described string) with arbitrary small descriptor
    desc = _encode_smallulong(r, r.choice([0x10, 0x20, 0x30, 0x40]))
    value = _atom_scalar(r)
    return bytes([DESCRIBED_TYPE]) + desc + value


def _encode_smallulong(r: random.Random, val: int) -> bytes:
    if val == 0:
        return bytes([ULONG0])
    if val < 256:
        return bytes([SMALLULONG, val & 0xFF])
    return bytes([ULONG]) + _put_ulong(val)


def _section_described(ul: int, value: bytes) -> bytes:
    # descriptor is a smallulong descriptor code
    if ul == 0:
        desc = bytes([ULONG0])
    elif ul < 256:
        desc = bytes([SMALLULONG, ul & 0xFF])
    else:
        desc = bytes([ULONG]) + _put_ulong(ul)
    return bytes([DESCRIBED_TYPE]) + desc + value


def _encode_list_from(items: List[bytes]) -> bytes:
    payload = b''.join(items)
    count = len(items)
    if count == 0:
        return bytes([LIST0])
    size = len(payload) + 1
    if size < 256 and count < 256:
        return bytes([LIST8, size & 0xFF, count & 0xFF]) + payload
    else:
        return bytes([LIST32]) + _put_uint(size) + _put_uint(count) + payload


def _section_header(r: random.Random) -> bytes:
    # header is a list of 5 fields: durable(boolean), priority(ubyte), ttl(ms)(uint), first-acquirer(boolean), delivery-count(uint)
    durable = _rand_bool(r)
    priority = bytes([UBYTE, r.randint(0, 9)])
    ttl = bytes([UINT]) + _put_uint(r.randint(0, 600000))
    first = _rand_bool(r)
    dcnt = bytes([UINT]) + _put_uint(r.randint(0, 10))
    fields = [durable, priority, ttl, first, dcnt]
    for i in range(5):
        if r.random() < 0.3:
            fields[i] = bytes([NULL])
    lst = _encode_list_from(fields)
    return _section_described(DESC_HEADER, lst)


def _section_properties(r: random.Random) -> bytes:
    # properties is a list of up to 13 fields. We'll populate a subset with optionals.
    def opt(v: bytes) -> bytes:
        return v if r.random() < 0.8 else bytes([NULL])

    fields = [
        opt(_atom_scalar(r)),                      # message-id
        opt(_encode_binary_pref(r, max_len=16)),  # user-id (binary)
        opt(_encode_string(r)),                   # to
        opt(_encode_string(r)),                   # subject
        opt(_encode_string(r)),                   # reply-to
        opt(_atom_scalar(r)),                     # correlation-id
        opt(_encode_symbol(r)),                   # content-type
        opt(_encode_symbol(r)),                   # content-encoding
        opt(bytes([TIMESTAMP]) + _put_long(int(time.time()*1000) + r.randint(0, 3600_000))),
        opt(bytes([TIMESTAMP]) + _put_long(int(time.time()*1000))),
        opt(_encode_string(r)),                   # group-id
        opt(bytes([UINT]) + _put_uint(r.getrandbits(32))),
        opt(_encode_string(r))
    ]
    lst = _encode_list_from(fields)
    return _section_described(DESC_PROPERTIES, lst)


def _encode_binary_pref(r: random.Random, max_len: int = 128) -> bytes:
    data = _rand_small_bytes(r, max_len)
    if len(data) < 256:
        return bytes([BINARY8, len(data)]) + data
    return bytes([BINARY32]) + _put_uint(len(data)) + data


def _section_application_properties(r: random.Random) -> bytes:
    # application-properties is a map with symbol keys -> simple scalar values
    pairs = r.randint(0, 5)
    entries = []
    for _ in range(pairs):
        key = _encode_symbol(r)
        # keep values scalar to limit size and ensure decodability
        val = _atom_scalar(r)
        entries.append(key + val)
    payload = b''.join(entries)
    count_entries = pairs * 2
    if len(payload) + 1 + 1 < 255 and count_entries < 255:
        total_size = len(payload) + 1
        mp = bytes([MAP8, total_size & 0xFF, count_entries & 0xFF]) + payload
    else:
        total_size = len(payload) + 4
        mp = bytes([MAP32]) + _put_uint(total_size) + _put_uint(count_entries) + payload
    return _section_described(DESC_APPLICATION_PROPERTIES, mp)


def _section_body(r: random.Random) -> bytes:
    # Choose one of data, amqp-sequence, or amqp-value
    t = r.choice(['data', 'sequence', 'value'])
    if t == 'data':
        binv = _encode_binary_pref(r, max_len=256)
        return _section_described(DESC_BODY_DATA, binv)
    if t == 'sequence':
        lst = _encode_list(r, max_elems=8)
        return _section_described(DESC_BODY_SEQUENCE, lst)
    val = _encode_any(r)
    return _section_described(DESC_BODY_VALUE, val)


def _build_message(r: random.Random) -> bytes:
    parts = []
    if r.random() < 0.9:
        parts.append(_section_header(r))
    if r.random() < 0.3:
        mp = _encode_map(r, max_pairs=3)
        parts.append(_section_described(DESC_DELIVERY_ANNOTATIONS, mp))
    if r.random() < 0.5:
        mp = _encode_map(r, max_pairs=3)
        parts.append(_section_described(DESC_MESSAGE_ANNOTATIONS, mp))
    if r.random() < 0.95:
        parts.append(_section_properties(r))
    if r.random() < 0.8:
        parts.append(_section_application_properties(r))
    parts.append(_section_body(r))
    if r.random() < 0.2:
        mp = _encode_map(r, max_pairs=2)
        parts.append(_section_described(DESC_FOOTER, mp))
    blob = b''.join(parts)
    if len(blob) > MAX_SIZE:
        blob = blob[:MAX_SIZE]
    return blob


def _build_single_value(r: random.Random) -> bytes:
    val = _encode_any(r)
    if len(val) > MAX_SIZE:
        val = val[:MAX_SIZE]
    return val


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # choose between single AMQP value (for pn_data_decode) and full message (for pn_message_decode)
    if r.random() < 0.6:
        buf = _build_message(r)
    else:
        buf = _build_single_value(r)
    if len(buf) > MAX_SIZE:
        buf = buf[:MAX_SIZE]
    return buf
